typedef struct {
    int bitsPerSample;
    int samplesPerPixel;
    int extraSamples;
    int *sampleInfo;
} TIFFInfo;

TIFFInfo* parseTIFF(const char* filename) {
    TIFF *tiff = TIFFOpen(filename, "r");
    if (!tiff) {
        fprintf(stderr, "Could not open TIFF file\n");
        return NULL;
    }

    TIFFInfo *info = (TIFFInfo *)malloc(sizeof(TIFFInfo));
    if (!info) {
        fclose(tiff);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    uint16 bitsPerSample;
    uint16 samplesPerPixel;
    uint16 extraSamples = 0;
    uint16 *sampleInfo = NULL;

    if (TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE, &bitsPerSample) != 1) {
        fprintf(stderr, "Could not get bits per sample\n");
        free(info);
        TIFFClose(tiff);
        return NULL;
    }

    switch (bitsPerSample) {
        case 1: case 2: case 4: case 8: case 16:
            info->bitsPerSample = bitsPerSample;
            break;
        default:
            fprintf(stderr, "Unsupported bits per sample: %d\n", bitsPerSample);
            free(info);
            TIFFClose(tiff);
            return NULL;
    }

    if (TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel) != 1) {
        fprintf(stderr, "Could not get samples per pixel\n");
        free(info);
        TIFFClose(tiff);
        return NULL;
    }
    info->samplesPerPixel = samplesPerPixel;

    if (TIFFGetField(tiff, TIFFTAG_EXTRASAMPLES, &extraSamples, &sampleInfo) != 1) {
        fprintf(stderr, "Could not get extra samples\n");
    }
    info->extraSamples = extraSamples;
    info->sampleInfo = sampleInfo;

    TIFFClose(tiff);
    return info;
}
