void print_ip_options(const uint8_t *packet, size_t length) {
    size_t offset = 0;
    while (offset < length) {
        uint8_t opt_type = packet[offset];
        uint8_t opt_len = packet[offset + 1];

        if (offset + opt_len > length) {
            printf("  [End of Options]\n");
            return;
        }

        printf("  Option Type: 0x%02X, Length: %u\n", opt_type, opt_len);

        switch (opt_type) {
            case 0xff: // End of Options
                printf("    [End of Options]\n");
                return;
            case 0x00: // No Operation
                printf("    [No Operation]\n");
                break;
            default:
                printf("    [Unknown Option]\n");
                break;
        }

        offset += opt_len;
    }
}

