#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

void analyze_sentence(const char *sentence) {
    int vowels = 0, uppercase = 0, lowercase = 0;

    for (int i = 0; sentence[i] != '\0'; i++) {
        char ch = sentence[i];
        if (ch >= 'A' && ch <= 'Z') {
            uppercase++;
            if (ch == 'A' || ch == 'E' || ch == 'I' || ch == 'O' || ch == 'U') {
                vowels++;
            }
        } else if (ch >= 'a' && ch <= 'z') {
            lowercase++;
            if (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u') {
                vowels++;
            }
        }
    }

    printf("Uppercase letters: %d\n", uppercase);
    printf("Lowercase letters: %d\n", lowercase);
    printf("Vowels: %d\n", vowels);
}

int main() {
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        exit(EXIT_FAILURE);
    } else if (pid == 0) {
        // Child process
        const char *sentence = "Hello, World!";
        analyze_sentence(sentence);
        exit(EXIT_SUCCESS);
    } else {
        // Parent process
        int status;
        if (waitpid(pid, &status, 0) == -1) {
            perror("waitpid");
            exit(EXIT_FAILURE);
        }
        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            printf("Child process executed successfully.\n");
        } else {
            printf("Child process failed.\n");
        }
    }

    return 0;
}
