#include <stdlib.h>
#include <stdio.h>

#define PAGE_SIZE 4096

struct pool {
    void **pages;
    size_t size;
    size_t pages_count;
    size_t element_size;
};

struct pool *init_pool(size_t element_size, size_t elements_count) {
    struct pool *pool = (struct pool *)__alloc_from_pool(sizeof(struct pool), NULL, 0);
    if (!pool) {
        return NULL;
    }

    pool->element_size = element_size;
    pool->pages_count = (elements_count + PAGE_SIZE - 1) / PAGE_SIZE;

    pool->pages = (void **)__alloc_from_pool(pool->pages_count * sizeof(void *), NULL, 0);
    if (!pool->pages) {
        __free_to_pool(pool);
        return NULL;
    }

    for (size_t i = 0; i < pool->pages_count; i++) {
        void *page = __alloc_from_pool(PAGE_SIZE, NULL, 0);
        if (!page) {
            __free_to_pool(pool);
            for (size_t j = 0; j < i; j++) {
                __free_to_pool(pool->pages[j]);
            }
            return NULL;
        }
        pool->pages[i] = page;
    }

    return pool;
}

void __free_to_pool(void *ptr) {
    free(ptr);
}
