struct Server {
    char hostname[256];
    int port;
};

struct ServerList {
    struct Server *servers;
    size_t count;
    size_t capacity;
};

struct ServerList *parse_server_list(const char *server_list) {
    struct ServerList *list = malloc(sizeof(struct ServerList));
    if (list == NULL)
        return NULL;

    list->servers = NULL;
    list->count = 0;
    list->capacity = 0;

    const char *start = server_list;
    const char *end = server_list;

    while (*end != '\0') {
        if (*end == ',') {
            size_t len = end - start;
            if (len > 0) {
                struct Server *new_server = realloc(list->servers, (list->count + 1) * sizeof(struct Server));
                if (new_server == NULL) {
                    free(list->servers);
                    free(list);
                    return NULL;
                }
                list->servers = new_server;

                strncpy(list->servers[list->count].hostname, start, len);
                list->servers[list->count].hostname[len] = '\0';

                // Parse port
                const char *port_start = strchr(start, ':');
                if (port_start != NULL) {
                    port_start++;
                    char *endptr;
                    list->servers[list->count].port = (int)strtol(port_start, &endptr, 10);
                    if (*endptr != '\0') {
                        free(list->servers);
                        free(list);
                        return NULL;
                    }
                }

                list->count++;
            }
            start = end + 1;
        }
        end++;
    }

    // Parse last server
    size_t len = end - start;
    if (len > 0) {
        struct Server *new_server = realloc(list->servers, (list->count + 1) * sizeof(struct Server));
        if (new_server == NULL) {
            free(list->servers);
            free(list);
            return NULL;
        }
        list->servers = new_server;

        strncpy(list->servers[list->count].hostname, start, len);
        list->servers[list->count].hostname[len] = '\0';

        // Parse port
        const char *port_start = strchr(start, ':');
        if (port_start != NULL) {
            port_start++;
            char *endptr;
            list->servers[list->count].port = (int)strtol(port_start, &endptr, 10);
            if (*endptr != '\0') {
                free(list->servers);
                free(list);
                return NULL;
            }
        }

        list->count++;
    }

    return list;
}

void free_server_list(struct ServerList *list) {
    free(list->servers);
    free(list);
}

int main() {
    const char *server_list = "localhost:11108, localhost:11109";
    struct ServerList *list = parse_server_list(server_list);

    if (list != NULL) {
        for (size_t i = 0; i < list->count; i++) {
            printf("Server %zu: %s:%d\n", i, list->servers[i].hostname, list->servers[i].port);
        }
        free_server_list(list);
    } else {
        printf("Failed to parse server list.\n");
    }

    return 0;
}
