#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Blob {
    int x, y; // Position on the grid
    int lifetime; // How long the blob will exist
    struct Blob *next;
} Blob;

typedef struct BlobList {
    Blob *head;
} BlobList;

void initBlobList(BlobList *list) {
    list->head = NULL;
}

void addBlob(BlobList *list, int x, int y, int lifetime) {
    Blob *newBlob = (Blob *)malloc(sizeof(Blob));
    newBlob->x = x;
    newBlob->y = y;
    newBlob->lifetime = lifetime;
    newBlob->next = list->head;
    list->head = newBlob;
}

void updateBlobs(BlobList *list) {
    Blob *current = list->head;
    Blob *prev = NULL;
    while (current != NULL) {
        current->lifetime--;
        if (current->lifetime <= 0) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            current = prev->next;
        } else {
            prev = current;
            current = current->next;
        }
    }
}

void printBlobs(BlobList *list) {
    Blob *current = list->head;
    while (current != NULL) {
        printf("Blob at (%d, %d) with lifetime %d\n", current->x, current->y, current->lifetime);
        current = current->next;
    }
}

int main() {
    BlobList list;
    initBlobList(&list);

    srand(time(0));

    for (int i = 0; i < 10; i++) {
        addBlob(&list, rand() % 10, rand() % 10, rand() % 10 + 1);
    }

    printBlobs(&list);

    updateBlobs(&list);

    printBlobs(&list);

    return 0;
}
