#include <cuda_runtime.h>
#include <cublas_v2.h>
#include <iostream>
#include <random>

int main() {
    int m, k, n;
    std::cout << "Enter matrix dimensions (m k n): ";
    std::cin >> m >> k >> n;

    // Initialize CUDA
    cudaSetDevice(0);
    cublasHandle_t handle;
    cublasCreate(&handle);

    // Allocate GPU memory for matrices
    float *d_A, *d_B, *d_C;
    cudaMalloc((void**)&d_A, m * k * sizeof(float));
    cudaMalloc((void**)&d_B, k * n * sizeof(float));
    cudaMalloc((void**)&d_C, m * n * sizeof(float));

    // Initialize random values for matrix A
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<> dis(0.0, 1.0);
    float *h_A = new float[m * k];
    for (int i = 0; i < m * k; ++i) {
        h_A[i] = dis(gen);
    }
    cudaMemcpy(d_A, h_A, m * k * sizeof(float), cudaMemcpyHostToDevice);
    delete[] h_A;

    // Initialize matrix B with random values
    float *h_B = new float[k * n];
    for (int i = 0; i < k * n; ++i) {
        h_B[i] = dis(gen);
    }
    cudaMemcpy(d_B, h_B, k * n * sizeof(float), cudaMemcpyHostToDevice);
    delete[] h_B;

    // Perform matrix multiplication C = A * B
    cublasSgemm(handle, CUBLAS_OP_N, CUBLAS_OP_N, m, n, k, 1.0, d_A, k, d_B, n, 0.0, d_C, n);

    // Copy result back to host
    float *h_C = new float[m * n];
    cudaMemcpy(h_C, d_C, m * n * sizeof(float), cudaMemcpyDeviceToHost);

    // Print result
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            std::cout << h_C[i * n + j] << " ";
        }
        std::cout << std::endl;
    }
    delete[] h_C;

    // Free GPU memory
    cudaFree(d_A);
    cudaFree(d_B);
    cudaFree(d_C);

    // Destroy CUDA handle
    cublasDestroy(handle);

    return 0;
}
