public class AESCipherExample {

    private static final String ALGORITHM = "AES/CBC/NoPadding";
    private static final String TRANSFORMATION = "PBKDF2WithHmacSHA1";
    private static final int AES_KEY_SIZE = 256;
    private static final int SALT_LENGTH = 16;
    private static final int ITERATION_COUNT = 65536;

    public static byte[] generateKey(char[] password, byte[] salt) throws Exception {
        SecretKeyFactory factory = SecretKeyFactory.getInstance(TRANSFORMATION);
        KeySpec spec = new PBEKeySpec(password, salt, ITERATION_COUNT, AES_KEY_SIZE);
        SecretKey secret = factory.generateSecret(spec);
        return secret.getEncoded();
    }

    public static byte[] encrypt(byte[] data, byte[] key, byte[] iv) throws Exception {
        SecretKeySpec secretKeySpec = new SecretKeySpec(key, "AES");
        IvParameterSpec ivParameterSpec = new IvParameterSpec(iv);
        Cipher cipher = Cipher.getInstance(ALGORITHM);
        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec, ivParameterSpec);
        return cipher.doFinal(data);
    }

    public static byte[] decrypt(byte[] encryptedData, byte[] key, byte[] iv) throws Exception {
        SecretKeySpec secretKeySpec = new SecretKeySpec(key, "AES");
        IvParameterSpec ivParameterSpec = new IvParameterSpec(iv);
        Cipher cipher = Cipher.getInstance(ALGORITHM);
        cipher.init(Cipher.DECRYPT_MODE, secretKeySpec, ivParameterSpec);
        return cipher.doFinal(encryptedData);
    }

    public static void main(String[] args) {
        try {
            char[] password = "password".toCharArray();
            byte[] salt = "random_salt_16".getBytes();
            byte[] data = "Hello, AES!".getBytes();

            byte[] key = generateKey(password, salt);
            byte[] iv = new byte[16]; // AES block size
            new java.security.SecureRandom().nextBytes(iv);

            byte[] encrypted = encrypt(data, key, iv);
            System.out.println("Encrypted: " + Base64.getEncoder().encodeToString(encrypted));

            byte[] decrypted = decrypt(encrypted, key, iv);
            System.out.println("Decrypted: " + new String(decrypted));
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
