import java.util.ArrayList;
import java.util.List;
import java.util.Random;

public class RandomObjectReplacer {

    private static final double MEAN = 0.0;
    private static final Random RANDOM = new Random();

    public static List<Integer> replaceWithGaussian(List<Integer> originalList) {
        double stdDev = 0.2 * originalList.size();
        List<Integer> newList = new ArrayList<>(originalList);

        for (int i = 0; i < originalList.size(); i++) {
            if (RANDOM.nextDouble() < 0.5) {
                int newValue = (int) (MEAN + RANDOM.nextGaussian() * stdDev);
                newList.set(i, newValue);
            }
        }

        return newList;
    }

    public static List<Integer> getAllDiscreteValues(List<Integer> originalList, int iterations) {
        List<Integer> discreteValues = new ArrayList<>();

        for (int i = 0; i < iterations; i++) {
            List<Integer> newList = replaceWithGaussian(originalList);
            for (Integer value : newList) {
                if (!discreteValues.contains(value)) {
                    discreteValues.add(value);
                }
            }
        }

        return discreteValues;
    }
}
