import java.io.IOException;

public class JsonGenerator {

    @Nonnull
    public static String toJson(@Nonnull Object object) throws IOException {
        return toJson(object, false);
    }

    private static String toJson(@Nonnull Object object, boolean prettyPrint) throws IOException {
        StringBuilder jsonBuilder = new StringBuilder();
        if (object instanceof String) {
            jsonBuilder.append("\"").append(escapeString((String) object)).append("\"");
        } else if (object instanceof Number) {
            jsonBuilder.append(object.toString());
        } else if (object instanceof Boolean) {
            jsonBuilder.append(object.toString());
        } else if (object instanceof Object[]) {
            jsonBuilder.append("[");
            boolean first = true;
            for (Object item : (Object[]) object) {
                if (!first) {
                    jsonBuilder.append(", ");
                }
                jsonBuilder.append(toJson(item, prettyPrint));
                first = false;
            }
            jsonBuilder.append("]");
        } else if (object instanceof java.util.Map) {
            jsonBuilder.append("{");
            boolean first = true;
            for (Object key : ((java.util.Map<?, ?>) object).keySet()) {
                if (!first) {
                    jsonBuilder.append(", ");
                }
                jsonBuilder.append("\"").append(escapeString(key.toString())).append("\": ");
                jsonBuilder.append(toJson(((java.util.Map<?, ?>) object).get(key), prettyPrint));
                first = false;
            }
            jsonBuilder.append("}");
        }
        return jsonBuilder.toString();
    }

    private static String escapeString(@Nonnull String str) {
        return str.replace("\"", "\\\"")
                     .replace("\b", "\\b")
                     .replace("\t", "\\t")
                     .replace("\n", "\\n")
                     .replace("\f", "\\f")
                     .replace("\r", "\\r");
    }
}
