import java.io.*;
import java.util.*;

public class FileFilter {

    public static List<String> filterFiles(String directory, String dataType) {
        List<String> filteredFiles = new ArrayList<>();
        File folder = new File(directory);
        File[] files = folder.listFiles();

        if (files != null) {
            for (File file : files) {
                if (file.isFile()) {
                    try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
                        Hashtable<?, ?> data = (Hashtable<?, ?>) ois.readObject();
                        if (data.containsKey(dataType)) {
                            filteredFiles.add(file.getAbsolutePath());
                        }
                    } catch (IOException | ClassNotFoundException e) {
                        System.err.println("Error reading file " + file.getAbsolutePath() + ": " + e.getMessage());
                    }
                }
            }
        }

        return filteredFiles;
    }

    public static void main(String[] args) {
        List<String> files = filterFiles("path/to/directory", "dataTypeToFilter");
        for (String file : files) {
            System.out.println(file);
        }
    }
}
