public class RemoteMethodExecutor {

    public Object executeMethod(String methodName, Object... args) throws IOException, ClassNotFoundException {
        Socket socket = new Socket("remote.server.com", 12345);
        ObjectOutputStream out = new ObjectOutputStream(socket.getOutputStream());
        ObjectInputStream in = new ObjectInputStream(socket.getInputStream());

        try {
            out.writeObject(new MethodCall(methodName, args));
            out.flush();

            Object result = in.readObject();
            return result;
        } finally {
            in.close();
            out.close();
            socket.close();
        }
