public class ProcessInstanceSerializer {

    public static ProcessInstance deserializeProcessInstance(byte[] serializedData) throws IOException, ClassNotFoundException {
        ByteArrayInputStream bis = new ByteArrayInputStream(serializedData);
        ObjectInputStream ois = new ObjectInputStream(bis);
        ProcessInstance deserializedInstance = (ProcessInstance) ois.readObject();
        ois.close();
        return deserializedInstance;
