        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        ObjectOutputStream oos = new ObjectOutputStream(bos);
        oos.writeObject(instance);
        oos.close();
        return bos.toByteArray();
    }

    public static boolean verifyInstanceSerialization(ProcessInstance original, ProcessInstance deserialized) {
        return original.getId().equals(deserialized.getId());
    }
