    try {
        Process process = processBuilder.start();

        StringBuilder outputBuilder = new StringBuilder();
        StringBuilder errorBuilder = new StringBuilder();

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                outputBuilder.append(line).append("\n");
                logger.debug("Exec [{}]: '{}'", "OUTPUT", line);
            }
        }

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                errorBuilder.append(line).append("\n");
                logger.debug("Exec [{}]: '{}'", "ERROR", line);
            }
        }

        int exitCode = process.waitFor();
        boolean exitVal = exitCode == 0;

        if (!exitVal) {
            logger.warn("Process exited with an error code: {}", exitCode);
        }

        updateProcessStatus(process, outputBuilder.toString(), errorBuilder.toString(), exitVal);
        return exitVal;
    } catch (IOException | InterruptedException e) {
        logger.error("An error occurred while executing the process: {}", e.getMessage());
        return false;
    }
}

private void updateProcessStatus(Process process, String output, String error, boolean isSuccessful) {
    try {
        int exitCode = process.exitValue();
        updateState(ProcessState.RUN, isSuccessful ? OnOffType.ON : OnOffType.OFF);
        updateState(ProcessState.EXIT, new DecimalType(exitCode));
        updateState(ProcessState.OUTPUT, new StringType(output + error));
    } catch (IllegalThreadStateException e) {
        logger.warn("Process has not exited yet, cannot update status.");
    }
}
