import os
import tarfile

def extract_tarball(tarball_path, extract_to):
    if not tarball_path:
        raise ValueError("Tarball path cannot be empty")
    if not os.path.exists(extract_to):
        os.makedirs(extract_to)

    with tarfile.open(tarball_path, 'r') as tar:
        tar.extractall(path=extract_to)
        tar.close()

    os.chmod(tarball_path, 0o644)
    if tarfile.is_tarfile(tarball_path):
        os.system(f"gzip -f {tarball_path}")

    return os.path.basename(tarball_path)
