import os
import tempfile
import subprocess

def get_mercurial_changeset_info(changeset_id):
    # Create a temporary directory
    with tempfile.TemporaryDirectory() as temp_dir:
        # Run the hg command to retrieve changeset information
        result = subprocess.run(['hg', 'log', '-r', changeset_id], cwd=temp_dir, capture_output=True, text=True)

        # Check if the command was successful
        if result.returncode != 0:
            raise Exception(f"Failed to retrieve changeset info: {result.stderr}")

        # Extract changeset information
        changeset_info = {}
        lines = result.stdout.split('\n')
        for line in lines:
            if line.startswith('tags:'):
                changeset_info['tags'] = line.split(': ')[1]
            elif line.startswith('date:'):
                changeset_info['date'] = line.split(': ')[1]
            elif line.startswith('author:'):
                changeset_info['author'] = line.split(': ')[1]
            elif line.startswith('parent:'):
                changeset_info['parent'] = line.split(': ')[1]
            elif line.startswith('summary:'):
                changeset_info['comment'] = line.split(': ')[1]

        return changeset_info
